24		VALID_ENVIRONMENTS.has(scriptArgs[0] ?? "") ? 1 : 0,
25	);
26	// Split remaining args into env-file paths and passthrough Vercel CLI flags.
27	// A bare token counts as a file only when it exists on disk, so flags and their
28	// values (e.g. `--scope my-team`) forward correctly regardless of argument order.
29	const files: string[] = [];
30	const passthroughArgs: string[] = [];
31	for (const arg of remainingArgs) {
32		if (!arg.startsWith("-") && existsSync(arg)) {
33			files.push(arg);
34		} else {
35			passthroughArgs.push(arg);
36		}
37	}
38	const vercelArgs = [...passthroughArgs, ...forwardedArgs];
39	const envFiles = files.length > 0 ? files : DEFAULT_FILES;
40	
41	if (envFiles.length === 0) {
42		console.log("No env files configured for this Vercel stack.");
43		process.exit(0);
44	}
45	
46	const env = new Map<string, string>();
47	
48	for (const file of envFiles) {
49		if (!existsSync(file)) {
50			console.warn(`Skipping missing env file: ${file}`);
51			continue;
52		}
53	
54		for (const [key, value] of Object.entries(
55			dotenv.parse(readFileSync(file, "utf8")),
56		)) {
57			if (SKIP_KEYS.has(key)) continue;
58			env.set(key, OVERRIDE_KEYS.get(key) ?? value);
59		}
60	}
61	
62	if (env.size === 0) {
63		console.log("No Vercel env vars found to sync.");
64		process.exit(0);
65	}
66	
67	const LOCAL_VALUE_PATTERN = /localhost|127\.0\.0\.1|0\.0\.0\.0|^file:/i;
68	const localKeys = [...env.entries()]
69		.filter(([, value]) => LOCAL_VALUE_PATTERN.test(value))
70		.map(([key]) => key);
71	if (localKeys.length > 0) {
72		console.warn(
73			`Warning: ${localKeys.join(", ")} look${localKeys.length === 1 ? "s" : ""} like local-only value(s). Update them in your .env file(s) and re-run this sync if your deployed app should not point at local endpoints.`,
74		);
75	}
76	
77	console.log(`Syncing ${env.size} env var(s) to Vercel ${environment}.`);
78	for (const [key, value] of env.entries()) {
79		const result = spawnSync(
80			VERCEL_COMMAND[0],
81			[
82				...VERCEL_COMMAND.slice(1),
83				"env",
84				"add",
85				key,
86				environment,
87				"--force",
88				"--yes",
89				"--non-interactive",
90				...vercelArgs,
91			],
92			{
93				input: `${value}\n`,
94				stdio: ["pipe", "inherit", "inherit"],
95				encoding: "utf8",
96				// Windows resolves bunx/npx/pnpm via .cmd shims, which need a shell
97				shell: process.platform === "win32",
98			},
99		);
100	
101		if (result.error) {
102			console.error(`Failed to sync ${key}: ${result.error.message}`);
103			process.exit(1);
104		}
105	
106		if (result.status !== 0) {
107			console.error(`Failed to sync ${key}`);
108			process.exit(result.status ?? 1);
109		}
110	}
111	
112	console.log("Vercel env sync complete. Redeploy for changes to take effect.");
